// Package brandgen renders the files that are generated from internal/brand: the
// frontend's theme tokens and brand constants, the macOS app bundle's Info.plist, and the
// app icon artwork that `magex brand:icons` renders into the raster icons.
//
// The generated files are committed. Write regenerates them (magex brand:generate), and
// Check reports any that drifted from internal/brand, so a test fails until they are
// regenerated. Output is byte-stable: rendering twice yields identical bytes.
package brandgen

import (
	"bytes"
	"encoding/xml"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"strings"
	"unicode"

	"github.com/mrz1836/nilbox/internal/brand"
)

// Generated file paths, relative to the repository root and slash-separated.
const (
	ThemeCSSPath  = "frontend/src/generated/theme.css"
	BrandTSPath   = "frontend/src/generated/brand.ts"
	BrandJSONPath = "frontend/src/generated/brand.json"
	InfoPlistPath = "build/darwin/Info.plist"
)

// Header marks every generated file whose format allows a comment.
const Header = "Code generated by internal/brandgen; DO NOT EDIT."

// Bundle metadata that does not come from internal/brand.
const (
	// MinimumMacOS is the oldest macOS release the app bundle supports.
	MinimumMacOS = "13.0"

	// PlaceholderVersion is the committed bundle version; builds stamp the real one on
	// their copy of the Info.plist.
	PlaceholderVersion = "0.0.0"
)

// File permissions for generated output. Git tracks only the executable bit.
const (
	dirPerm  fs.FileMode = 0o750
	filePerm fs.FileMode = 0o600
)

// ErrStale is returned by Check when a generated file is missing or out of date.
var ErrStale = errors.New("generated files are out of date")

// File is one generated file: its slash-separated path relative to the repository root
// and its exact contents.
type File struct {
	Path    string
	Content []byte
}

// token is one palette color, named for CSS and TypeScript.
type token struct {
	css   string // kebab-case CSS custom property suffix, e.g. "background"
	ts    string // camelCase TypeScript key, e.g. "background"
	light string
	dark  string
}

// Files renders every generated file from internal/brand.
func Files() []File {
	tokens := paletteTokens()

	return []File{
		{Path: ThemeCSSPath, Content: themeCSS(tokens)},
		{Path: BrandTSPath, Content: brandTS(tokens)},
		{Path: BrandJSONPath, Content: brandJSON()},
		{Path: InfoPlistPath, Content: infoPlist()},
		{Path: IconSVGPath, Content: iconSVG()},
	}
}

// Write renders every generated file into root, creating directories as needed. Files
// whose contents already match are left untouched.
func Write(root string) error {
	for _, f := range Files() {
		path := filepath.Join(root, filepath.FromSlash(f.Path))

		current, err := os.ReadFile(path) //nolint:gosec // generated paths are constants under root
		if err == nil && bytes.Equal(current, f.Content) {
			continue
		}

		if err = os.MkdirAll(filepath.Dir(path), dirPerm); err != nil {
			return fmt.Errorf("create directory for %s: %w", f.Path, err)
		}

		if err = os.WriteFile(path, f.Content, filePerm); err != nil {
			return fmt.Errorf("write %s: %w", f.Path, err)
		}
	}

	return nil
}

// Check reports whether every generated file under root matches internal/brand. It
// returns an error wrapping ErrStale that names each missing or outdated file.
func Check(root string) error {
	var stale []string

	for _, f := range Files() {
		current, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(f.Path))) //nolint:gosec // generated paths are constants under root

		switch {
		case errors.Is(err, fs.ErrNotExist):
			stale = append(stale, f.Path+" (missing)")
		case err != nil:
			return fmt.Errorf("read %s: %w", f.Path, err)
		case !bytes.Equal(current, f.Content):
			stale = append(stale, f.Path)
		}
	}

	if len(stale) > 0 {
		return fmt.Errorf("%w: %s; run magex brand:generate", ErrStale, strings.Join(stale, ", "))
	}

	return nil
}

// paletteTokens pairs each Palette field's light and dark values, in field order.
func paletteTokens() []token {
	light := reflect.ValueOf(brand.Light)
	dark := reflect.ValueOf(brand.Dark)
	typ := light.Type()
	tokens := make([]token, 0, typ.NumField())

	for i := range typ.NumField() {
		name := typ.Field(i).Name
		tokens = append(tokens, token{
			css:   kebab(name),
			ts:    lowerFirst(name),
			light: light.Field(i).String(),
			dark:  dark.Field(i).String(),
		})
	}

	return tokens
}

// themeCSS renders the CSS custom properties for both themes. The light theme is the
// default, the dark theme follows the system appearance, and an explicit data-theme
// attribute on the root element overrides both.
func themeCSS(tokens []token) []byte {
	var b strings.Builder

	b.WriteString("/* " + Header + " */\n")
	b.WriteString("/* Theme tokens from internal/brand. Light is the default; dark follows the system. */\n\n")

	cssBlock(&b, ":root", "", "light", tokens, false)
	b.WriteString("\n@media (prefers-color-scheme: dark) {\n")
	cssBlock(&b, ":root", "  ", "dark", tokens, true)
	b.WriteString("}\n\n")
	cssBlock(&b, ":root[data-theme='light']", "", "light", tokens, false)
	b.WriteString("\n")
	cssBlock(&b, ":root[data-theme='dark']", "", "dark", tokens, true)

	return []byte(b.String())
}

// cssBlock writes one rule that sets color-scheme and every brand token.
func cssBlock(b *strings.Builder, selector, indent, scheme string, tokens []token, dark bool) {
	b.WriteString(indent + selector + " {\n")
	b.WriteString(indent + "  color-scheme: " + scheme + ";\n")

	for _, t := range tokens {
		value := t.light
		if dark {
			value = t.dark
		}

		b.WriteString(indent + "  --brand-" + t.css + ": " + value + ";\n")
	}

	b.WriteString(indent + "}\n")
}

// brandTS renders the brand identity, the mark, and both palettes as TypeScript constants.
func brandTS(tokens []token) []byte {
	var b strings.Builder

	b.WriteString("// " + Header + "\n")
	b.WriteString("// Product identity, the logo mark, and theme palettes from internal/brand.\n\n")
	b.WriteString("export const brand = {\n")
	b.WriteString("  name: " + jsString(brand.Name) + ",\n")
	b.WriteString("  slug: " + jsString(brand.Slug) + ",\n")
	b.WriteString("  tagline: " + jsString(brand.Tagline) + ",\n")
	b.WriteString("  mark: {\n")
	b.WriteString("    width: " + strconv.Itoa(brand.MarkWidth) + ",\n")
	b.WriteString("    height: " + strconv.Itoa(brand.MarkHeight) + ",\n")
	b.WriteString("    path: " + jsString(brand.MarkPath) + ",\n")
	b.WriteString("    highlight: " + jsString(brand.MarkHighlight) + ",\n")
	b.WriteString("  },\n")
	b.WriteString("} as const\n\n")
	b.WriteString("export const palettes = {\n")
	tsPalette(&b, "light", tokens, false)
	tsPalette(&b, "dark", tokens, true)
	b.WriteString("} as const\n\n")
	b.WriteString("export type PaletteToken = keyof (typeof palettes)['light']\n")

	return []byte(b.String())
}

// tsPalette writes one palette object literal.
func tsPalette(b *strings.Builder, name string, tokens []token, dark bool) {
	b.WriteString("  " + name + ": {\n")

	for _, t := range tokens {
		value := t.light
		if dark {
			value = t.dark
		}

		b.WriteString("    " + t.ts + ": " + jsString(value) + ",\n")
	}

	b.WriteString("  },\n")
}

// brandJSON renders the identity fields the frontend build reads (for the page title).
func brandJSON() []byte {
	return []byte("{\n" +
		"  \"name\": " + jsString(brand.Name) + ",\n" +
		"  \"tagline\": " + jsString(brand.Tagline) + "\n" +
		"}\n")
}

// infoPlist renders the macOS bundle metadata. Keys are sorted, as plutil writes them.
func infoPlist() []byte {
	automation := brand.Name + " opens your terminal app (such as iTerm2) to start coding sessions in your local clones."

	entries := []struct {
		key   string
		value string // empty for the boolean entry
	}{
		{"CFBundleDevelopmentRegion", "en"},
		{"CFBundleDisplayName", brand.Name},
		{"CFBundleExecutable", brand.Slug},
		{"CFBundleIconFile", IconFile},
		{"CFBundleIdentifier", brand.BundleID},
		{"CFBundleInfoDictionaryVersion", "6.0"},
		{"CFBundleName", brand.Name},
		{"CFBundlePackageType", "APPL"},
		{"CFBundleShortVersionString", PlaceholderVersion},
		{"CFBundleVersion", PlaceholderVersion},
		{"LSMinimumSystemVersion", MinimumMacOS},
		{"NSAppleEventsUsageDescription", automation},
		{"NSHighResolutionCapable", ""},
	}

	var b strings.Builder

	b.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
	b.WriteString(`<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">` + "\n")
	b.WriteString("<!-- " + Header + " -->\n")
	b.WriteString(`<plist version="1.0">` + "\n<dict>\n")

	for _, e := range entries {
		b.WriteString("\t<key>" + xmlText(e.key) + "</key>\n")

		if e.value == "" {
			b.WriteString("\t<true/>\n")

			continue
		}

		b.WriteString("\t<string>" + xmlText(e.value) + "</string>\n")
	}

	b.WriteString("</dict>\n</plist>\n")

	return []byte(b.String())
}

// jsString renders s as a double-quoted string literal that is valid in both JSON and
// TypeScript.
func jsString(s string) string {
	var b strings.Builder

	b.WriteByte('"')

	for _, r := range s {
		switch {
		case r == '"' || r == '\\':
			b.WriteByte('\\')
			b.WriteRune(r)
		case r < 0x20 || r == 0x2028 || r == 0x2029:
			fmt.Fprintf(&b, "\\u%04x", r)
		default:
			b.WriteRune(r)
		}
	}

	b.WriteByte('"')

	return b.String()
}

// xmlText escapes s for XML character data.
func xmlText(s string) string {
	var b strings.Builder

	// Writing to a strings.Builder cannot fail.
	_ = xml.EscapeText(&b, []byte(s))

	return b.String()
}

// kebab converts a Go field name such as "SurfaceRaised" to "surface-raised".
func kebab(name string) string {
	var b strings.Builder

	for i, r := range name {
		if unicode.IsUpper(r) {
			if i > 0 {
				b.WriteByte('-')
			}

			r = unicode.ToLower(r)
		}

		b.WriteRune(r)
	}

	return b.String()
}

// lowerFirst converts a Go field name such as "SurfaceRaised" to "surfaceRaised".
func lowerFirst(name string) string {
	if name == "" {
		return name
	}

	r := []rune(name)
	r[0] = unicode.ToLower(r[0])

	return string(r)
}
